# quick use exact determinant varying boundary pressure terms signs / zero compare existing
import numpy as np
from model import geometry,mode

def root(s,p,modeb):
 t=geometry({'stretch':s,'pressure':p})[1];J=s*t;c=1-2*np.log(J);b=t*t;P=p*J/1e6;A=s*s+c+2;D=b+c+2;E=(2+c)**2
 def det(y):
  f=lambda Q:(A-b*Q-y)*(s*s-D*Q-y)+Q*E
  v=[f(0),f(1),f(2)];aa=(v[2]-2*v[1]+v[0])/2;bb=v[1]-v[0]-aa;cc=v[0]
  ts=[]
  for Q in np.roots([aa,bb,cc]):
   q=np.sqrt(Q+0j);q=q if q.real>=0 else -q;q11=A-b*q*q-y
   # modeb 0 real P; 1 P=0; -1 signs inverted
   pp= P if modeb==0 else 0
   ts.append([-1j*(b*q*q*(2+c)+(c-pp)*q11),q*(D*q11-(2+pp)*(2+c))])
  return np.linalg.det(np.array(ts).T).imag
 ys=np.linspace(.001,s*s*.999,500)
 for a,bx in zip(ys[:-1],ys[1:]):
  if det(a)*det(bx)<0:return a+(bx-a)*(-det(a))/(det(bx)-det(a))
for p in [0,2e5,8e5]: print(p, 'correct',root(1,p,0),'P0',root(1,p,1),'existing',mode({'stretch':1,'pressure':p}))
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:30000}); text(r.output);

